import { handleMiddleware } from "@opennextjs/aws/core/routing/middleware.js";
import type { InternalEvent } from "@opennextjs/aws/types/open-next.js";
import { vi } from "vitest";

// Matchers generated by Next.js 16.4.5 for `["/admin/:path*", "/api/:path*"]` with `basePath: "/docs"` and i18n.
// The locale follows the basePath.
vi.mock("@opennextjs/aws/adapters/config/index.js", () => ({
  NextConfig: {
    basePath: "/docs",
    i18n: {
      defaultLocale: "en",
      locales: ["en", "fr"],
    },
  },
  MiddlewareManifest: {
    sortedMiddleware: ["/"],
    middleware: {
      "/": {
        files: [],
        name: "middleware",
        page: "/",
        matchers: [
          {
            regexp:
              "^\\/docs(?:\\/(_next\\/data\\/[^/]{1,}))?(?:\\/((?!_next\\/)[^/.]{1,}))\\/admin(?:\\/((?:[^\\/#\\?]+?)(?:\\/(?:[^\\/#\\?]+?))*))?(\\.json|\\.rsc|\\.segments\\/.+\\.segment\\.rsc)?[\\/#\\?]?$",
            originalSource: "/admin/:path*",
          },
          {
            regexp:
              "^\\/docs(?:\\/(_next\\/data\\/[^/]{1,}))?(?:\\/((?!_next\\/)[^/.]{1,}))\\/api(?:\\/((?:[^\\/#\\?]+?)(?:\\/(?:[^\\/#\\?]+?))*))?(\\.json|\\.rsc|\\.segments\\/.+\\.segment\\.rsc)?[\\/#\\?]?$",
            originalSource: "/api/:path*",
          },
          // Matchers with `locale: false` have no locale group, the locale is part of their source.
          {
            regexp:
              "^\\/docs(?:\\/(_next\\/data\\/[^/]{1,}))?\\/en\\/reports(?:\\/((?:[^\\/#\\?]+?)(?:\\/(?:[^\\/#\\?]+?))*))?(\\.json|\\.rsc|\\.segments\\/.+\\.segment\\.rsc)?[\\/#\\?]?$",
            originalSource: "/en/reports/:path*",
          },
          {
            regexp:
              "^\\/docs(?:\\/(_next\\/data\\/[^/]{1,}))?\\/fr\\/offres(?:\\/((?:[^\\/#\\?]+?)(?:\\/(?:[^\\/#\\?]+?))*))?(\\.json|\\.rsc|\\.segments\\/.+\\.segment\\.rsc)?[\\/#\\?]?$",
            originalSource: "/fr/offres/:path*",
          },
        ],
      },
    },
    functions: {},
    version: 2,
  },
  FunctionsConfigManifest: undefined,
  PrerenderManifest: {
    preview: {
      previewModeId: "preview",
    },
  },
}));

function createEvent(
  rawPath: string,
  cookies: Record<string, string> = {},
  headers: Record<string, string> = {},
) {
  return {
    type: "core",
    method: "GET",
    rawPath,
    url: `https://example.com${rawPath}`,
    body: Buffer.from(""),
    headers,
    query: {},
    cookies,
    remoteAddress: "::1",
  } satisfies InternalEvent;
}

function createMiddlewareLoader() {
  const middleware = vi
    .fn()
    .mockResolvedValue(new Response("auth required", { status: 401 }));
  const middlewareLoader = vi.fn().mockResolvedValue({ default: middleware });
  return { middleware, middlewareLoader };
}

describe("handleMiddleware with basePath and i18n", () => {
  it.each([
    ["/docs/admin", "/docs/en/admin"],
    ["/docs/admin/users", "/docs/en/admin/users"],
    ["/docs/api/users", "/docs/en/api/users"],
    ["/docs/en/admin", "/docs/en/admin"],
    ["/docs/fr/admin", "/docs/fr/admin"],
  ])(
    "runs the middleware for %s with the locale after the basePath",
    async (rawPath, middlewarePath) => {
      const { middleware, middlewareLoader } = createMiddlewareLoader();

      const result = await handleMiddleware(
        createEvent(rawPath),
        "",
        middlewareLoader,
      );

      expect(middlewareLoader).toHaveBeenCalledOnce();
      expect(middleware).toHaveBeenCalledWith(
        expect.objectContaining({
          url: `https://example.com${middlewarePath}`,
          nextConfig: expect.objectContaining({ basePath: "/docs" }),
        }),
      );
      expect(result).toEqual(expect.objectContaining({ statusCode: 401 }));
    },
  );

  it("uses the detected locale", async () => {
    const { middleware, middlewareLoader } = createMiddlewareLoader();

    await handleMiddleware(
      createEvent("/docs/admin", { NEXT_LOCALE: "fr" }),
      "",
      middlewareLoader,
    );

    expect(middleware).toHaveBeenCalledWith(
      expect.objectContaining({ url: "https://example.com/docs/fr/admin" }),
    );
  });

  describe("with a matcher for a single locale", () => {
    it.each([
      ["no locale preference", {}, {}, "/docs/en/reports"],
      ["a NEXT_LOCALE cookie", { NEXT_LOCALE: "fr" }, {}, "/docs/fr/reports"],
      [
        "an Accept-Language header",
        {},
        { "accept-language": "fr" },
        "/docs/fr/reports",
      ],
    ])(
      "runs the middleware matching the default locale with %s",
      async (_, cookies, headers, middlewarePath) => {
        const { middleware, middlewareLoader } = createMiddlewareLoader();

        const result = await handleMiddleware(
          createEvent("/docs/reports", cookies, headers),
          "",
          middlewareLoader,
        );

        expect(middleware).toHaveBeenCalledWith(
          expect.objectContaining({
            url: `https://example.com${middlewarePath}`,
          }),
        );
        expect(result).toEqual(expect.objectContaining({ statusCode: 401 }));
      },
    );

    it("runs the middleware matching the locale preferred by the visitor", async () => {
      const { middleware, middlewareLoader } = createMiddlewareLoader();

      await handleMiddleware(
        createEvent("/docs/offres", { NEXT_LOCALE: "fr" }),
        "",
        middlewareLoader,
      );

      expect(middleware).toHaveBeenCalledWith(
        expect.objectContaining({ url: "https://example.com/docs/fr/offres" }),
      );
    });

    it.each([
      ["/docs/fr/reports", { NEXT_LOCALE: "en" }],
      ["/docs/en/offres", { NEXT_LOCALE: "fr" }],
      ["/docs/offres", {}],
    ])(
      "does not run the middleware for %s with the cookies %o",
      async (rawPath, cookies) => {
        const { middlewareLoader } = createMiddlewareLoader();
        const event = createEvent(rawPath, cookies);

        const result = await handleMiddleware(event, "", middlewareLoader);

        expect(middlewareLoader).not.toHaveBeenCalled();
        expect(result).toBe(event);
      },
    );
  });

  it.each(["/docs/public", "/docs", "/admin"])(
    "does not run the middleware for %s",
    async (rawPath) => {
      const { middlewareLoader } = createMiddlewareLoader();
      const event = createEvent(rawPath);

      const result = await handleMiddleware(event, "", middlewareLoader);

      expect(middlewareLoader).not.toHaveBeenCalled();
      expect(result).toBe(event);
    },
  );
});
